    # If the number of free cells is not divisible by 5, return NO
    if free_cells % 5 != 0:
        return "NO"

    # Try to place the pieces
    def dfs(x, y, placed_pieces):
        if placed_pieces == free_cells // 5:
            return True

        if x == n:
            return dfs(0, y + 1, placed_pieces)

        if y == n:
            return True

        if board[x][y] == '#':
            return dfs(x + 1, y, placed_pieces)

        # Try placing a piece in all possible orientations
        for dx, dy in [(0, 1), (1, 0), (1, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < n and board[nx][ny] == '.':
                # Place the piece
                board[x][y] = '#'
                board[nx][ny] = '#'
                if dx == 0:
                    board[x][y + 1] = '#'
                    board[nx][ny + 1] = '#'
                elif dy == 0:
                    board[x + 1][y] = '#'
                    board[nx + 1][ny] = '#'
                else:
                    board[x + 1][y] = '#'
                    board[x][y + 1] = '#'

                if dfs(x + 1, y, placed_pieces + 1):
                    return True

                # Remove the piece
                board[x][y] = '.'
                board[nx][ny] = '.'
                if dx == 0:
                    board[x][y + 1] = '.'
