    # Count the number of free cells
    free_cells = sum(row.count('.') for row in board)

    # If the number of free cells is not divisible by 5, it's impossible to tile
    if free_cells % 5 != 0:
        return "NO"

    # Function to check if a piece can be placed at (r, c)
    def can_place_piece(r, c):
        # Check all possible orientations of the piece
        directions = [
            [(0, 0), (0, 1), (0, 2), (1, 1)],  # L shape
            [(0, 0), (0, 1), (1, 0), (1, 1)],  # L shape
            [(0, 0), (1, 0), (1, 1), (1, 2)],  # L shape
            [(0, 0), (0, 1), (1, 0), (2, 0)],  # L shape
            [(0, 0), (1, 0), (1, 1), (2, 1)],  # L shape
            [(0, 0), (0, 1), (1, 1), (1, 2)],  # L shape
            [(0, 0), (1, 0), (1, 1), (2, 0)],  # L shape
            [(0, 0), (0, 1), (1, 1), (2, 1)]   # L shape
        ]

        for d in directions:
            valid = True
            for dr, dc in d:
                nr, nc = r + dr, c + dc
                if not (0 <= nr < n and 0 <= nc < n and board[nr][nc] == '.'):
                    valid = False
                    break
            if valid:
                return True
        return False

    # Try to place pieces on the board
    def place_pieces(board, placed):
        if placed == free_cells // 5:
            return True

        for r in range(n):
            for c in range(n):
                if board[r][c] == '.':
                    if can_place_piece(r, c):
                        # Place the piece
                        for dr, dc in [(0, 0), (0, 1), (0, 2), (1, 1)]:
                            board[r + dr][c + dc] = '#'
                        if place_pieces(board, placed + 1):
                            return True
                        # Remove the piece
                        for dr, dc in [(0, 0), (0, 1), (0, 2), (1, 1)]:
                            board[r + dr][c + dc] = '.'
                    break
            else:
                continue
            break
        return False

    # Convert board to a list of lists for easier manipulation
    board = [list(row) for row in board]

    # Attempt to place pieces
    if place_pieces(board, 0):
        return "YES"
    else:
        return "NO"

